    adcs_vec3_t m_unconstrained;
    double b2;
    double parallel_coeff;
    adcs_vec3_t parallel_part;
    adcs_vec3_t perp;
    double norm_m;
    double scale_factor;

    // 1. Validate inputs
    if ((field_body_t == NULL) || (field_rate_t_s == NULL) || (command == NULL)) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        return ADCS_E_NULL;
    }
    if ((!adcs_is_finite_vec3(field_body_t)) || (!adcs_is_finite_vec3(field_rate_t_s)) ||
        (!isfinite(normalized_gain_nm_s_t)) || (!isfinite(max_dipole_a_m2)) ||
        (normalized_gain_nm_s_t < 0.0) || (max_dipole_a_m2 < 0.0)) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    // 2. Calculate B dot B
    b2 = adcs_vec3_dot(field_body_t, field_body_t);

    // 3. Check for degenerate field magnitude (||B|| <= 1e-12 => B.B <= 1e-24)
    if (b2 <= 1.0e-24) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }

    // 4. Project Bdot onto B to get parallel component
    // rate_parallel = (Bdot . B) * B / b2
    parallel_coeff = adcs_vec3_dot(field_rate_t_s, field_body_t) / b2;
    parallel_part = adcs_vec3_scale(field_body_t, parallel_coeff);

    // 5. Calculate perpendicular component: Bdot_perp = Bdot - rate_parallel
    perp = adcs_vec3_sub(field_rate_t_s, &parallel_part);

    // 6. Calculate unconstrained dipole: m = -gain * Bdot_perp / b2
    m_unconstrained = adcs_vec3_scale(&perp, -normalized_gain_nm_s_t / b2);

    // 7. Apply Euclidean-norm limit preserving direction
    norm_m = adcs_vec3_norm(&m_unconstrained);

    if (norm_m > max_dipole_a_m2) {
        // Scaled: mask=7
        scale_factor = max_dipole_a_m2 / norm_m;
        m_unconstrained = adcs_vec3_scale(&m_unconstrained, scale_factor);
        command->saturated_axes = 7U;
    } else {
        // Not scaled: mask=0
        command->saturated_axes = 0U;
    }

    // 8. Output result
    command->command = m_unconstrained;

    return ADCS_OK;
}

